function isoAngle(role,suffix,angle){const a=iso(angle),answer=(180-angle)/2;return calc(role,suffix,[20],B(`AB=AC and ∠A=${angle}°. Find each base angle.`,`AB=AC，∠A=${angle}°。求每個底角。`),`(180-${angle})/2`,answer,[['Equal sides give equal opposite base angles: ∠B=∠C.','等邊對等角，所以 ∠B=∠C。'],[`2∠B=180°−${angle}°, so each base angle is ${answer}°.`,`2∠B=180°−${angle}°，所以每個底角為${answer}°。`]],{unit:'°',audit:{...a,requestedAngle:'B',expectedAngle:answer},diagram:geometry(a.points,[['A','B','C']],{equalSegments:[[['A','B'],['A','C']]]})});}
