function dividePoly(role,suffix,ls,original,result,nonzeroVariables,intermediate){
 const restrictions=nonzeroVariables.map(v=>`${v}≠0`).join(', '),zh=nonzeroVariables.map(v=>`${v}≠0`).join('、');
 return poly(role,suffix,ls,original,result,rules.division,intermediate,{prompt:B(`Simplify; retain the original divisor restriction ${restrictions}.`,`化簡；保留原除式限制 ${zh}。`),answer:B(`${result}; ${restrictions}.`,`${result}；${zh}。`),audit:{kind:'polynomial',original,result,variables:['x','y'],nonzeroVariables}});
}
