function scientific(role,suffix,value,mantissa,exponent,fields={}){
 return Q(role,suffix,[48],fields.prompt||B(`Write ${value} in scientific notation with 1≤|a|<10.`,`把 ${value} 寫成科學記數法，要求1≤|a|<10。`),B(`${mantissa}×10^${exponent}.`,`${mantissa}×10^${exponent}。`),
 [[`Move the decimal point to obtain mantissa ${mantissa}, whose absolute value is between 1 and 10.`,`移動小數點，得尾數${mantissa}，其絕對值介乎1與10之間。`],[`Compensate with 10^${exponent}, so ${value}=${mantissa}×10^${exponent}.`,`用10^${exponent}補償，所以 ${value}=${mantissa}×10^${exponent}。`],['Check the sign and the decimal order of magnitude.','核對正負號及小數的數量級。']],
 [['Keep any negative sign; it does not change the decimal shift count.','保留原負號；負號不影響移動小數點的位數。'],['For a number with absolute value below 1, the power of 10 is negative.','絕對值小於1時，10的指數為負。'],[`Use ${mantissa}×10^${exponent}; check by converting back.`,`寫成 ${mantissa}×10^${exponent}，再還原核對。`]],
 [['Use a normalized nonzero mantissa and an integer exponent.','使用標準化的非零尾數及整數指數。'],['Preserve the original value and sign.','保持原值及正負號。']],{type:'short',space:'working',expression:value,answerExpression:`${mantissa}\\times10^{${exponent}}`,audit:{kind:'scientific-notation',value,mantissa,exponent},...fields});
}
