function word(role,suffix,ls,prompt,left,right,solution,denominators,excluded,model,quantities,work,unit){
 return equation(role,suffix,ls,left,right,[solution],denominators,excluded,work,{prompt,expression:undefined,answerExpression:`${left}=${right}`,answer:B(`x=${solution} ${unit}; it is positive and satisfies the original model.`,`x=${solution} ${unit==='days'?'天':'km/h'}；為正且符合原模型。`),audit:{kind:'word-model',model,quantities,left,right,solutions:[String(solution)],variable:'x',denominators,excluded:excluded.map(String)},hints:[B('Express each rate or travel time using the same unknown and consistent units.','用同一未知數及一致單位表示每項效率或行程時間。'),B(model==='work-rate'?'Add the completed work, or equate the sum of rates to the combined rate.':'Use distance÷speed for each time and identify whether times are equal or differ.',model==='work-rate'?'把完成工作量相加，或令效率和等於合作效率。':'每項時間用路程÷速度表示，再辨認相等或相差關係。'),B('Solve, substitute into the original model, and reject forbidden or nonpositive contextual values.','解方程，代回原模型，排除禁值及不符合情境的非正值。')]});
}
